    delivery_est_breadcrumb: "Сроки доставки",
    terms_title: "Условия использования",
    terms_meta_desc: "Условия использования сервиса RateShips — бесплатный калькулятор стоимости международной доставки.",
    terms_s1_title: "1. Описание сервиса",
    terms_s1_body: "RateShips — это бесплатный информационный сервис для сравнения стоимости международной доставки. Мы предоставляем ориентировочные цены на основе опубликованных тарифных сеток перевозчиков. Сервис предназначен исключительно для информационных целей.",
    terms_s2_title: "2. Точность информации",
    terms_s2_body: "Все цены, сроки доставки и таможенная информация являются приблизительными оценками. Мы не гарантируем точность, полноту или актуальность представленных данных. Фактические тарифы могут отличаться в зависимости от перевозчика, размеров посылки, дополнительных сборов и других факторов.",
    terms_s3_title: "3. Отсутствие аффилиации",
    terms_s3_body: "RateShips не является аффилированным лицом, партнёром или представителем каких-либо перевозчиков или курьерских служб. Мы не продаём услуги доставки и не обрабатываем отправления. Все товарные знаки и названия перевозчиков принадлежат их соответствующим владельцам.",
    terms_s4_title: "4. Отказ от гарантий",
    terms_s4_body: "Сервис предоставляется «как есть» без каких-либо гарантий. Мы не несём ответственности за убытки, возникшие в результате использования информации с нашего сайта. Пользователь несёт ответственность за проверку актуальных тарифов и условий непосредственно у выбранного перевозчика перед отправкой.",
    terms_s5_title: "5. Ответственность пользователя",
    terms_s5_body: "Пользователь обязан самостоятельно проверять все тарифы, правила и ограничения у перевозчика перед оформлением отправления. RateShips не несёт ответственности за решения, принятые на основе информации, представленной на сайте.",
    terms_s6_title: "6. Изменение условий",
    terms_s6_body: "Мы оставляем за собой право изменять настоящие условия в любое время. Продолжение использования сервиса после внесения изменений означает согласие с обновлёнными условиями.",
    last_updated_march: "Последнее обновление: март 2026",
    privacy_title: "Политика конфиденциальности",
    privacy_meta_desc: "Политика конфиденциальности RateShips — как мы собираем и используем данные.",
    privacy_s1_title: "1. Аналитика и отслеживание",
    privacy_s1_body: "Мы используем Google Analytics и Google Tag Manager (GTM) для сбора анонимной статистики о посещениях сайта. Это помогает нам понимать, как пользователи взаимодействуют с сервисом, и улучшать его. Собираемые данные включают: страницы посещений, время на сайте, тип устройства, географическое расположение (на уровне страны) и источник перехода.",
    privacy_s2_title: "2. Реклама",
    privacy_s2_body: "Мы используем Google AdSense для показа рекламы на сайте. AdSense может использовать файлы cookie для показа персонализированной рекламы на основе ваших предыдущих посещений нашего и других сайтов. Вы можете отказаться от персонализированной рекламы в настройках рекламы Google.",
    privacy_s3_title: "3. Сбор электронной почты",
    privacy_s3_body: "Если вы подписываетесь на нашу рассылку, мы сохраняем ваш адрес электронной почты для отправки обновлений о новых функциях, изменениях тарифов и полезных руководствах по доставке. Вы можете отписаться в любое время, перейдя по ссылке в нижней части любого письма.",
    privacy_s4_title: "4. Локальное хранилище",
    privacy_s4_body: "Мы используем localStorage в вашем браузере для сохранения избранных маршрутов доставки и пользовательских настроек (валюта, единицы веса). Эти данные хранятся только на вашем устройстве и не передаются на наши серверы.",
    privacy_s5_title: "5. Файлы cookie",
    privacy_s5_body: "Наш сайт использует файлы cookie для работы Google Analytics, Google Tag Manager и Google AdSense. Эти cookie помогают анализировать трафик и показывать релевантную рекламу. Вы можете управлять cookie в настройках вашего браузера.",
    privacy_s6_title: "6. Продажа данных",
    privacy_s6_body: "Мы не продаём, не обмениваем и не передаём ваши персональные данные третьим лицам, за исключением случаев, описанных в данной политике (аналитика и реклама). Мы не собираем имена, адреса или платёжную информацию.",
    privacy_s7_title: "7. Контакт",
    privacy_s7_body: "По вопросам конфиденциальности обращайтесь по адресу: ",
